package com.bank.gov.service;

import com.bank.gov.model.Migration;
import java.util.*;
import java.util.logging.Logger;

// Flyway-style: apply ordered, immutable migrations exactly once; record history.
public class MigrationRunner {
    private static final Logger log = Logger.getLogger(MigrationRunner.class.getName());
    private final SortedSet<Integer> applied = new TreeSet<>(); // schema_history

    public void apply(List<Migration> migrations) {
        migrations.sort(Comparator.comparingInt(m -> m.version));
        for (Migration m : migrations) {
            if (applied.contains(m.version)) {
                log.info(() -> "Skip V" + m.version + " (already applied)");
                continue;
            }
            if (m.concurrent) {
                log.info(() -> "Running V" + m.version + " OUTSIDE a transaction (concurrent DDL)");
            } else {
                log.info(() -> "Running V" + m.version + " in a transaction");
            }
            log.info(() -> "  -> " + m.sql);
            applied.add(m.version); // record in history exactly once
        }
        log.info(() -> "Applied versions: " + applied);
    }
}
