package com.bank.gov.service;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// Shows that a blocking build stalls writers while a concurrent build does not.
public class IndexBuildSim {
    private static final Logger log = Logger.getLogger(IndexBuildSim.class.getName());

    public int simulate(boolean concurrent) throws InterruptedException {
        AtomicInteger writesCompleted = new AtomicInteger();
        final boolean[] indexLockHeld = { !concurrent }; // plain build holds a write lock

        Thread writer = new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                while (indexLockHeld[0]) { sleep(2); }   // blocked only when plain build locks
                writesCompleted.incrementAndGet();
                sleep(5);
            }
        });
        Thread builder = new Thread(() -> { sleep(60); indexLockHeld[0] = false; }); // build finishes

        writer.start(); builder.start();
        writer.join(300); builder.join();
        int done = writesCompleted.get();
        log.info(() -> (concurrent ? "CONCURRENTLY" : "PLAIN") + " build: writes completed during build = " + done);
        return done;
    }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException ignored) {} }
}
