package com.bank.gov;

import com.bank.gov.model.Migration;
import com.bank.gov.service.IndexBuildSim;
import com.bank.gov.service.MigrationRunner;
import java.util.*;

public class GovApplication {
    public static void main(String[] args) throws InterruptedException {
        // Versioned, ordered, reviewed migrations (Flyway-style).
        List<Migration> migrations = new ArrayList<>(List.of(
            new Migration(2, "add_nullable_col", "ALTER TABLE accounts ADD COLUMN x NUMERIC NULL", false),
            new Migration(6, "add_txn_index", "CREATE INDEX CONCURRENTLY idx_txn_account ON transactions(account_id)", true)
        ));
        new MigrationRunner().apply(migrations);

        // Index build impact on concurrent writers.
        IndexBuildSim sim = new IndexBuildSim();
        int plain = sim.simulate(false);
        int concurrent = sim.simulate(true);
        System.out.println("Writes during PLAIN build: " + plain + " (blocked)");
        System.out.println("Writes during CONCURRENT build: " + concurrent + " (not blocked)");
    }
}
